/** Parses CSV text into rows of strings. The first row is the header. */
export function parseCsv(text) {
  const lines = text.trim().split("\n");
  const header = lines[0].split(",");
  return lines.slice(1).map((line) => {
    const cells = line.split(",");
    return Object.fromEntries(header.map((key, i) => [key, cells[i]]));
  });
}
/** Amounts are kept in cents to avoid floating point drift. */
export function toCents(amount) {
  return Math.floor(Number(amount) * 100);
}

export function formatCents(cents, currency = "USD") {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  return `${sign}${currency} ${Math.floor(abs / 100)}.${abs % 100}`;
}
